/// <summary>
/// The <c> ISDIntgDMFFormBrowser </c> class is used for displaying Staging Data into <c>DMFDataVizualization</c> form grid.
/// </summary>
class ISDIntgDMFFormBrowser
{
    container con;
}

Method.Source:
public Container parmCon(container _con = con)
{
    con = _con;
    return con;
}

/// <summary>
/// View form data will display form controls to view the staging data into Grid using DMFDataVizualization form.
/// </summary>
/// <param name="_dMFDefinitionGroupExecution">
/// <c>_dMFDefinitionGroupExecution</c>to view.
/// </param>
public void viewFormData(DMFDefinitionGroupExecution _dMFDefinitionGroupExecution, boolean _showAllFields = false)
{
    #File
    #DMF

    Form                        formBrowser;
    Object                      formRun;
    FormBuildDesign             formBuildDesign;
    FormBuildDataSource         formBuildDataSource;
    FormBuildGridControl        formBuildGridControl;
    FormBuildTabControl         formBuildTabControl;
    FormBuildTabPageControl     formBuildTabPageControl;
    FormBuildGroupControl       formBuildGroupControl;
    FormGridControl             formGridControl;
    FormDataSource              formDataSource;
    FormBuildControl            formBuildControlLoc;

    Args                        args;
    Args                        browserArgs;
    SysDictField                sysDictField;
    IndexId                     uniqueIndexId;
    SysDictIndex                keyIndex;

    QueryBuildRange             qbRange;
    DictTable                   dictTable;
    DMFEntity                   entity;
    DictField                   isDictFieldTime;

    int                         i;
    int                         k;
    int                         idx;
    int                         fieldCount;
    int                         m;
    container                   primaryFields;
    Set                         setAlphabetic = new Set (Types::String);
    SetEnumerator               enumerator;
    Map                         map = new Map(Types::String, Types::Integer);
    SysDictField                dictField;
    FieldId                     fieldId;
    FieldId                     fieldIdLoc;
    int                         arrayIndex;

    select firstOnly EntityTable, EntityName from entity
        where entity.EntityName == _dMFDefinitionGroupExecution.Entity;

    if (entity.EntityTable)
    {
        dictTable = new DictTable(tableName2id(entity.EntityTable));

        uniqueIndexId = dictTable.primaryIndex();

        if (!uniqueIndexId)
        {
            uniqueIndexId = dictTable.indexUnique();
        }

        if (!uniqueIndexId)
        {
            throw error("@DMF1939");
        }
        keyIndex = new SysDictIndex(dictTable.id(), uniqueIndexId);

        k = keyIndex.numberOfFields();

        browserArgs = new Args();
        browserArgs.name(formstr(DMFDataVizualization));
        formRun     = classfactory.formRunClass(browserArgs);
        formBrowser = formRun.form();
        //formBrowser.design
        str dsName = 'ds';
        formBuildDataSource = formBrowser.dataSource(1);
        formBuildDataSource.name(dsName);
        formBuildDataSource.table(dictTable.id());
        formBuildDataSource.autoQuery(true);
        formBuildDataSource.linkType(0);
        formBuildDataSource.allowCreate(false);
        formBuildDataSource.allowDelete(true);
        formBuildDataSource.allowEdit(true);

        formBuildDesign = formBrowser.design();
        formBuildDesign.caption(entity.EntityName + #delimiterSpace + #colon);
        formBuildDesign.widthValue(#FormWidth);
        formBuildDesign.heightValue(#FormHeight);

        // Form Tab Control
        formBuildTabControl = formBuildDesign.addControl(FormControlType::Tab, identifierStr("formBuildTabControl"));
        formBuildTabControl.widthMode(FormWidth::ColumnWidth);
        formBuildTabControl.heightMode(FormHeight::ColumnHeight);
        formBuildTabControl.dataSource(dsName);

        // Form TabPage Control
        formBuildTabPageControl = formBuildTabControl.addControl(FormControlType::TabPage, #Overview);
        formBuildTabPageControl.caption(#Overview);
        formBuildTabPageControl.widthMode(FormWidth::ColumnWidth);
        formBuildTabPageControl.heightMode(FormHeight::ColumnHeight);
        formBuildTabPageControl.dataSource(dsName);

        // Form TabPage --> Group Control
        formBuildGroupControl = formBuildTabPageControl.addControl(FormControlType::Group, #Group);
        formBuildGroupControl.dataSource(dsName);
        formBuildGroupControl.widthMode(FormWidth::ColumnWidth);
        formBuildGroupControl.heightMode(FormHeight::ColumnHeight);

        // Form Grid Controls
        formBuildGridControl = formBuildDesign.control(#DMFFormBrowserGrid);
        formBuildGridControl.dataSource(dsName);
        formBuildGridControl.widthMode(FormWidth::ColumnWidth);
        formBuildGridControl.heightMode(FormHeight::ColumnHeight);
        idx = formBuildGridControl.id();

        if (dictTable.fieldName2Id(identifierStr(IsSelected)))
        {
            formBuildGridControl.addDataField(formBuildDataSource.id(), dictTable.fieldName2Id(identifierStr(IsSelected)));
            primaryFields = [dictTable.fieldName2Id(identifierStr(IsSelected))];
        }

        if (dictTable.fieldName2Id(identifierStr(TransferStatus)))
        {
            formBuildGridControl.addDataField(formBuildDataSource.id(), dictTable.fieldName2Id(identifierStr(TransferStatus)));
            primaryFields += [dictTable.fieldName2Id(identifierStr(TransferStatus))];

        }
        for (m = 1; m<=k; m++)
        {
            FormBuildControl ctrl = formBuildGridControl.addDataField(formBuildDataSource.id(), keyIndex.field(m));
            if (conFind([identifierstr(DefinitionGroup),identifierstr(ExecutionId)],fieldId2Name(dictTable.id(),keyIndex.field(m))))
            {
                ctrl.visible(false);
            }
            primaryFields += [keyIndex.field(m)];
        }

        fieldCount = dictTable.fieldCnt();
        for(i = 1; i < fieldCount; i++)
        {
            sysDictField = new SysDictField(dictTable.id(), dictTable.fieldCnt2Id(i));

            DMFSourceXMLToEntityMap sourceMap;
            for(arrayIndex = 1; arrayIndex <= sysDictField.arraySize(); arrayIndex++)
            {
                if (!_showAllFields)
                {
                    select firstonly sourceMap
                                where sourceMap.DefinitionGroup == _dMFDefinitionGroupExecution.DefinitionGroup &&
                                      sourceMap.Entity == _dMFDefinitionGroupExecution.Entity &&
                                      sourceMap.EntityField == sysDictField.name();
                }

                if (!sysDictField.isSystem() && (sourceMap || (_showAllFields)))
                {
                    if (!conFind(primaryFields, dictTable.fieldCnt2Id(i)))
                    {
                        // DMF Migration
                        // DictField cannot be assigned to SysDictField
                        if(arrayIndex > 1)
                        {
                            fieldIdLoc = fieldId2Ext(dictTable.fieldCnt2Id(i), arrayIndex);
                            dictField = new SysDictField(dictTable.id(), fieldIdLoc);
                        }
                        else
                        {
                            dictField = new SysDictField(dictTable.id(), dictTable.fieldCnt2Id(i));
                        }

                        if (map.exists(dictField.label()))
                        {
                            map.insert(dictField.name(), dictField.id());
                            setAlphabetic.add(dictField.name());
                            continue;
                        }
                        map.insert(dictField.label(), dictField.id());
                        setAlphabetic.add(dictField.label());
                    }
                }
            }
        }

        enumerator = setAlphabetic.getEnumerator();

        while(enumerator.moveNext())
        {
            formBuildControlLoc = formBuildGridControl.addDataField(formBuildDataSource.id(), map.lookup(enumerator.current()));
            fieldid = map.lookup(enumerator.current());
            isDictFieldTime = new DictField(dictTable.id(), fieldid);
            if (isDictFieldTime && (isDictFieldTime.baseType() == Types::UtcDateTime))
            {
                con += [formBuildControlLoc.id()];
            }
            formBuildGridControl.allowEdit(boolean::true);
        }

        this.parmCon(con);
        args = new Args();
        args.object(formBrowser);
        args.record(_dMFDefinitionGroupExecution);
        args.parmObject(this);
        args.parmEnum(_showAllFields);

        formRun = classfactory.formRunClass(args);
        formRun.init();
        formDataSource = formRun.dataSource();
        if (fieldName2id(tableName2id(entity.EntityTable), fieldStr(DMFExecution,ExecutionId)))
        {
            qbRange        = formDataSource.queryBuildDataSource().addRange(fieldName2id(tableName2id(entity.EntityTable), fieldStr(DMFExecution,ExecutionId)));
            qbRange.value(_dMFDefinitionGroupExecution.ExecutionId);
            qbRange.status(RangeStatus::Locked);
        }
        else
        {
            qbRange        = formDataSource.queryBuildDataSource().addRange(fieldName2id(tableName2id(entity.EntityTable), fieldStr(Common, RecId)));
            qbRange.value(strFmt("%1..%2",_dMFDefinitionGroupExecution.StartRecId, _dMFDefinitionGroupExecution.EndRecId));
            qbRange.status(RangeStatus::Locked);

            formDataSource.allowEdit(false);
            formDataSource.allowCreate(false);
            formDataSource.allowDelete(false);
        }

        qbRange = formDataSource.queryBuildDataSource().addRange(dictTable.fieldName2Id(identifierStr(TransferStatus)));
        qbRange.value(SysQuery::valueNot(DMFTransferStatus::Duplicate));
        qbRange.status(RangeStatus::Locked);

        formRun.run();

        formGridControl = formRun.control(idx);
        formGridControl.setFocus();
        formGridControl.showRowLabels(true);
        formRun.detach();

        // Decompose the object
        dictTable    = null;
        sysDictField = null;
    }
    else
    {
        throw error(strFmt("@DMF214", tableStr(DMFDefinitionGroupExecution)));
    }
}

/// <summary>
/// Creates an instance and holds the provided <c>ISDIntgDMFFormBrowser</c> object.
/// </summary>
/// <remarks>
/// When the instance gets out of scope or the <c>ISDIntgDMFFormBrowser.finalize</c> method is called
/// </remarks>
/// <returns>
/// The instance of the class
/// </returns>
public static ISDIntgDMFFormBrowser construct()
{
    return new ISDIntgDMFFormBrowser();
}

public static void main(Args _args)
{
    ISDIntgDMFFormBrowser  formBrowser = ISDIntgDMFFormBrowser::construct();

    if (_args.dataset() == tableNum(DMFDefinitionGroupExecution))
    {
        formBrowser.viewFormData(_args.record());
    }
}

/// <summary>
/// Function to return the packed query run object.
/// </summary>
/// <param name="queryContainer">
/// A container with a query.
/// </param>
/// <returns>
/// A query run object.
/// </returns>
public static container showQuery(container queryContainer)
{
    container  con = queryContainer;
    QueryRun   qRun = new QueryRun(queryContainer);
    qRun.saveUserSetup(false);
    if (qRun && qRun.prompt())
    {
        con = qRun.pack();
    }
    return con;
}
